<template><ul v-if="items.length" class="alert-feed"><li v-for="item in items.slice(0,maxItems)" :key="item.id"><time>{{ formatTime(item.occurred_at) }}</time><b :class="item.severity">{{ item.risk_code || item.module }}</b><span>{{ item.summary }}</span><code>{{ sourceLabel(item.client_ip) }}</code></li></ul><p v-else class="empty">{{ emptyText }}</p></template>
<script setup lang="ts">type AlertItem={id:string;occurred_at:string;module:string;severity:string;risk_code?:string;client_ip?:string;summary:string}; withDefaults(defineProps<{items:AlertItem[];maxItems?:number;emptyText?:string}>(),{maxItems:7,emptyText:'当前窗口暂无风险告警'}); const formatTime=(v:string)=>new Date(v).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}); const sourceLabel=(v?:string)=>v||'内部 / 测试'</script>
<style scoped>.alert-feed{display:flex;flex:1;flex-direction:column;margin:0;padding:6px 13px;list-style:none;overflow:hidden}.alert-feed li{display:grid;grid-template-columns:58px 78px minmax(0,1fr) auto;align-items:center;gap:8px;min-height:0;flex:1;border-bottom:1px solid var(--screen-line-soft);font-size:var(--fs-screen-label)}.alert-feed li:last-child{border-bottom:0}.alert-feed time,.alert-feed code{color:var(--screen-text-muted);font:var(--fs-screen-code) var(--font-code);white-space:nowrap}.alert-feed code{max-width:96px;overflow:hidden;text-overflow:ellipsis;text-align:right}.alert-feed b{overflow:hidden;padding:2px 5px;color:var(--risk-medium);background:rgba(255,181,69,.10);font-size:var(--fs-screen-code);text-align:center;text-overflow:ellipsis;white-space:nowrap}.alert-feed b.high,.alert-feed b.critical{color:var(--risk-critical);background:rgba(255,67,99,.11)}.alert-feed span{overflow:hidden;color:var(--screen-text-secondary);text-overflow:ellipsis;white-space:nowrap}.empty{display:grid;flex:1;place-items:center;margin:0;color:var(--screen-text-faint);font-size:var(--fs-screen-label)}</style>
